// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 amount) public {
        amount = bound(amount, 1, address(this).balance > 0 ? address(this).balance : 1 ether);
        vm.deal(address(this), amount);
        payable(address(c)).transfer(amount);

        Reverter r = new Reverter();
        address actor = address(0xA11CE);
        vm.deal(actor, 1 wei);

        bool ok;
        vm.prank(actor);
        try c.sendTo(address(r), amount) { ok = true; } catch { ok = false; }

        // General rule: a failed payout must revert sendTo (no silent success).
        assertTrue(!ok);
    }
}

contract Reverter {
    fallback() external payable { revert(); }
}

