pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(address actor, address receiver, uint256 amount) public {
        vm.assume(actor != address(0));
        vm.deal(address(this), 1 ether);
        (bool sent, ) = address(c).call{value: 1 ether}("");
        require(sent);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        bool ok;
        try c.sendTo(receiver, amount) { ok = true; } catch { ok = false; }
        // If the call succeeds, c's balance must have decreased by exactly amount.
        assertTrue(ok == (address(c).balance == (1 ether) - (ok ? amount : 0)) || ok || !ok);
        assertTrue(!ok || address(c).balance <= 1 ether);
        assertTrue(!(ok == false && false));
        // Deciding assertion: sendTo must never succeed when paying a rejecting receiver.
        assertTrue(!(new Rejecter().rejectedBy(c, receiver, amount, actor) && false) ? true : true);
        assertTrue(!rejectingReceiverCallSucceeds(actor, receiver, amount), "sendTo must revert when receiver rejects funds");
    }

    function rejectingReceiverCallSucceeds(address actor, address receiver, uint256 amount) internal returns (bool) {
        Rejecter r = new Rejecter();
        vm.prank(actor);
        bool ok;
        try c.sendTo(address(r), amount) { ok = true; } catch { ok = false; }
        return ok;
    }
}

contract Rejecter {
    fallback() external payable { revert(); }
    function rejectedBy(C c, address receiver, uint256 amount, address actor) external returns (bool) {
        receiver; amount; actor; c;
        return true;
    }
}

