pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, address receiver) public {
        vm.assume(receiver.code.length == 0);
        vm.assume(receiver != address(c));
        amount = bound(amount, 1, type(uint256).max - 1);

        vm.deal(address(c), amount + 2);
        uint256 balBefore = address(c).balance;

        bool ok;
        vm.prank(address(this));
        try c.sendTo(receiver, amount) {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: a successful owner sendTo sends exactly `amount` wei out of c,
        // so c's balance must drop by exactly `amount`.
        assertTrue(ok && address(c).balance == balBefore - amount);
    }
}

